package com.asmj.marketplace.category.service; import com.asmj.marketplace.category.model.Category; import com.asmj.marketplace.category.repository.CategoryRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.time.Instant; import java.util.*; @Service @RequiredArgsConstructor public class CategoryService {private final CategoryRepository repo;public List<Category> all(){return repo.findByActiveTrue();}public List<Category> adminAll(){return repo.findAll();}public Category save(Category c){c.setCreatedAt(Instant.now());return repo.save(c);}public Category update(String id,Category c){Category x=repo.findById(id).orElseThrow();x.setName(c.getName());x.setSlug(c.getSlug());x.setDescription(c.getDescription());x.setIcon(c.getIcon());x.setParentId(c.getParentId());x.setAttributes(c.getAttributes());x.setActive(c.isActive());return repo.save(x);}public void delete(String id){if(!repo.findByParentId(id).isEmpty())throw new IllegalArgumentException("Delete or move this category’s subcategories before deleting the parent category");repo.deleteById(id);}}
